CREATE TABLE fallback_policies(
 id TEXT PRIMARY KEY, profile TEXT NOT NULL REFERENCES profiles(id), name TEXT NOT NULL,
 revision INTEGER NOT NULL, definition TEXT NOT NULL, digest TEXT NOT NULL,
 UNIQUE(profile,name,revision), UNIQUE(profile,name,digest));
CREATE TABLE fallback_dependencies(policy_id TEXT NOT NULL REFERENCES fallback_policies(id), query_id TEXT NOT NULL REFERENCES saved_queries(id), PRIMARY KEY(policy_id,query_id));
CREATE TABLE fallback_bindings(
 profile TEXT NOT NULL REFERENCES profiles(id), catalog TEXT NOT NULL REFERENCES catalogs(id),
 policy_id TEXT NOT NULL REFERENCES fallback_policies(id), query_id TEXT NOT NULL REFERENCES saved_queries(id),
 layout TEXT NOT NULL, generation INTEGER NOT NULL DEFAULT 0,
 enabled INTEGER NOT NULL DEFAULT 0, interval_seconds INTEGER NOT NULL DEFAULT 60,
 max_changes INTEGER NOT NULL DEFAULT 100, max_removals INTEGER NOT NULL DEFAULT 0,
 next_attempt REAL NOT NULL DEFAULT 0, PRIMARY KEY(profile,catalog));
CREATE TABLE fallback_entries(
 id TEXT PRIMARY KEY, profile TEXT NOT NULL, catalog TEXT NOT NULL, item_id TEXT NOT NULL REFERENCES items(id),
 role TEXT NOT NULL, part INTEGER, variant TEXT NOT NULL DEFAULT '',
 policy_id TEXT NOT NULL REFERENCES fallback_policies(id),
 file_id TEXT REFERENCES files(id), revision TEXT, tier INTEGER, tier_name TEXT,
 path TEXT, active INTEGER NOT NULL DEFAULT 1, state TEXT NOT NULL,
 generation INTEGER NOT NULL, published_generation INTEGER NOT NULL DEFAULT 0,
 evidence TEXT NOT NULL DEFAULT '{}',
 FOREIGN KEY(profile,catalog) REFERENCES fallback_bindings(profile,catalog));
CREATE INDEX fallback_entries_scope ON fallback_entries(profile,catalog,active,path);
CREATE TABLE fallback_history(id INTEGER PRIMARY KEY AUTOINCREMENT, profile TEXT NOT NULL, catalog TEXT NOT NULL, entry_id TEXT NOT NULL, generation INTEGER NOT NULL, decision TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE fallback_health(profile TEXT NOT NULL, catalog TEXT NOT NULL, entry_id TEXT NOT NULL, file_id TEXT NOT NULL, revision TEXT NOT NULL, healthy_since REAL NOT NULL, successes INTEGER NOT NULL, last_check REAL NOT NULL, PRIMARY KEY(profile,catalog,entry_id,file_id));
CREATE TABLE fallback_probe_slots(id INTEGER PRIMARY KEY, owner TEXT, pid INTEGER);
INSERT INTO fallback_probe_slots(id) VALUES (1),(2),(3),(4),(5),(6),(7),(8);
CREATE TABLE fallback_epoch(id INTEGER PRIMARY KEY CHECK(id=1), generation INTEGER NOT NULL);
INSERT INTO fallback_epoch VALUES (1,0);
CREATE TABLE api_logical_demands(principal TEXT NOT NULL REFERENCES api_principals(id), idempotency_key TEXT NOT NULL, body TEXT NOT NULL, request_id TEXT NOT NULL REFERENCES api_requests(id), PRIMARY KEY(principal,idempotency_key));
